using Dip.Web.Components; using Dip.Web.Services; var builder=WebApplication.CreateBuilder(args);builder.Services.AddRazorComponents().AddInteractiveServerComponents();builder.Services.AddHttpClient<ApiClient>(c=>c.BaseAddress=new Uri(builder.Configuration["Api:BaseUrl"]??"https://localhost:7001/"));var app=builder.Build();app.UseHttpsRedirection();app.UseStaticFiles();app.UseAntiforgery();app.MapRazorComponents<App>().AddInteractiveServerRenderMode();app.Run();